export function validateCoupon(code: string) {
  if (code.trim().length === 0) {
    return { ok: false, reason: "Invalid" };
  }
  if (code.length < 8) {
    return { ok: false, reason: "Invalid" };
  }
  return { ok: true };
}

edits.newText:
export function validateCoupon(code: string) {
  if (code.trim().length === 0) {
    return { ok: false, reason: "Missing coupon code" };
  }
  if (code.length < 8) {
    return { ok: false, reason: "Invalid" };
  }
  return { ok: true };
}
